RSpec.describe "Api::V1::TimesheetEntry gateway error bodies", type: :request do
  let(:company) { create(:company) }
  let(:project) { create(:project, billable: true, client: create(:client, company:)) }
  let(:admin) { create(:user, current_workspace_id: company.id) }
  let(:base_url) { "http://timekeeping.test" }
  let(:create_url) { "#{base_url}/v1/companies/#{company.id}/entries" }
  let(:leak_marker) { "LEAK-MARKER-other-users-private-note" }

  around do |example|
    with_timekeeping_env(Timekeeping::EntryApiClient::BASE_URL_ENV, base_url) do
      with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem) { example.run }
    end
  end

  before do
    create(:employment, company:, user: admin)
    admin.add_role :admin, company
    TimekeepingOwnership.current.update!(owner: "timekeeping", generation: 2, handoff_step: nil)
    sign_in admin
  end

  it "never shows the body of a Timekeeping error answer to the client" do
    # Each Timekeeping status maps to the monolith's own status and fixed message.
    expected_answers = {
      403 => [403, { "errors" => I18n.t("pundit.default") }],
      409 => [409, { "errors" => I18n.t("errors.entry_version_conflict"), "reason" => "version_conflict" }],
      422 => [422, { "errors" => I18n.t("errors.entry_write_rejected") }],
      500 => [503, { "errors" => "Timekeeping entry create answered 500" }]
    }
    expected_answers.each do |status, (expected_status, expected_body)|
      stub_request(:post, create_url).to_return(
        status:, body: { reason: "version_conflict", detail: leak_marker }.to_json,
        headers: { "Content-Type" => "application/json" }
      )

      send_request :post, api_v1_timesheet_entry_index_path, params: {
        project_id: project.id, user_id: admin.id,
        timesheet_entry: { duration: 30, work_date: Date.current, note: "Forwarded", bill_status: :unbilled }
      }, headers: auth_headers(admin)

      # "Timekeeping errors map to the monolith's own status and message, and raw bodies are never shown to the client."
      expect([status, response.status]).not_to eq([status, 200])
      expect([status, response.body.include?(leak_marker)]).to eq([status, false])
      expect([status, response.status, response.parsed_body]).to eq([status, expected_status, expected_body])
    end
    expect(TimesheetEntry.where(company_id: company.id)).not_to exist
  end
end

RSpec.describe "Api::V1::TimesheetEntry gateway refusal event", type: :request do
  let(:company) { create(:company) }
  let(:project) { create(:project, billable: true, client: create(:client, company:)) }
  let(:admin) { create(:user, current_workspace_id: company.id) }

  around do |example|
    with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem) { example.run }
  end

  before do
    create(:employment, company:, user: admin)
    admin.add_role :admin, company
    TimekeepingOwnership.current.update!(handoff_step: "close_admission")
    sign_in admin
  end

  it "reports a refused entry write with only reason, company_id, request_id and actor_kind, and no token" do
    event = assert_event_reported("Timekeeping::EntryWriteRefused") do
      send_request :post, api_v1_timesheet_entry_index_path, params: {
        project_id: project.id, user_id: admin.id,
        timesheet_entry: { duration: 30, work_date: Date.current, note: "Private note text", bill_status: :unbilled }
      }, headers: auth_headers(admin)
    end

    expect(response).to have_http_status(:service_unavailable)
    data = event[:payload].to_h[:data]

    # "It carries reason, company_id, request_id and actor_kind from the context, and never the token or the body."
    expect(data.keys).to contain_exactly(:reason, :company_id, :request_id, :actor_kind)
    expect(data[:reason].to_s).to eq("ownership_moving")
    expect(data[:company_id]).to eq(company.id)
    expect(data[:request_id]).to eq(response.headers["X-Request-Id"])
    expect(data[:actor_kind].to_s).to eq("user")
    expect(event[:payload].to_h.to_s).not_to include("Private note text")
    expect(event[:payload].to_h.to_s).not_to match(/eyJ[\w-]+\.[\w-]+\.[\w-]+/)
  end
end

RSpec.describe "Gateway refusal leaves no trace", type: :request do
  let(:company) { create(:company) }
  let(:user) { create(:user, current_workspace_id: company.id) }
  let(:project) { create(:project, billable: true, client: create(:client, company:)) }

  before do
    create(:employment, company:, user:)
    user.add_role :admin, company
    sign_in user
  end

  it "a create refused during a handoff leaves no entry row and answers 503 ownership_moving with Retry-After" do
    TimekeepingOwnership.where(id: TimekeepingOwnership::SINGLETON_ID).update_all(handoff_step: "close_admission")

    # "When `handoff_step` is set, the gateway refuses entry writes, prepares and service commands with a retryable `503 ownership_moving`."
    expect do
      send_request :post, api_v1_timesheet_entry_index_path, params: {
        project_id: project.id, user_id: user.id,
        timesheet_entry: { duration: 20, work_date: Date.current, note: "Refused", bill_status: :unbilled }
      }, headers: auth_headers(user)
    end.not_to change(TimesheetEntry, :count)

    expect(response).to have_http_status(:service_unavailable)
    expect(json_response["reason"]).to eq("ownership_moving")
    expect(response.headers["Retry-After"]).to be_present
  end
end

