  around do |example|
    with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem) do
      with_timekeeping_env(Timekeeping::EntryApiClient::BASE_URL_ENV, "http://timekeeping.test") { example.run }
    end
  end

  before do
    create(:employment, company:, user:)
    user.add_role :admin, company
    TimekeepingOwnership.current.update!(owner: "timekeeping", generation: 2, handoff_step: nil)
    fake.generation = 2
    fake.register_company(id: company.id, edit_days: company.timesheet_edit_days)
    fake.register_user(id: user.id, company_id: company.id, role: "admin")
    fake.register_project(id: project.id, company_id: company.id)
    route_timekeeping_to_fake(fake, base_url: "http://timekeeping.test")
    sign_in user
  end

  it "a forwarded create, update and destroy succeed with no timesheet_entries row ever written" do
    # "An entry created while Timekeeping owns the data can be updated and deleted at once while snapshot delivery is paused"
    expect do
      send_request :post, api_v1_timesheet_entry_index_path, params: {
        project_id: project.id, user_id: user.id,
