RSpec.describe "Api::V1::TimesheetEntry gateway legacy writer marker", type: :request, committed_data: true do
  let(:marker_company) { create(:company) }
  let(:marker_project) { create(:project, billable: true, client: create(:client, company: marker_company)) }
  let(:marker_user) do
    create(:user, current_workspace_id: marker_company.id).tap do |user|
      create(:employment, company: marker_company, user:)
      user.add_role :employee, marker_company
    end
  end

  # Reads the writer setting while the entry's after_create event fires,
  # which is inside the gateway's write transaction.
  let(:marker_probe) do
    Class.new do
      attr_reader :seen

      def emit(event)
        return unless event[:name] == "TimesheetEntries::Created"

        @seen = ActiveRecord::Base.connection.select_value("SELECT current_setting('miru.writer', true)")
      end
    end.new
  end

  # "A legacy write reads `current_setting('miru.writer', true)` as `legacy_gateway` from inside the write, and an empty value after commit."
  it "a legacy create runs as legacy_gateway inside the write, commits the entry, and leaves the setting empty after commit" do
    sign_in marker_user
    params = {
      project_id: marker_project.id,
      timesheet_entry: { duration: 45, work_date: Date.current, note: "Legacy marker", bill_status: :unbilled }
    }

    Rails.event.subscribe(marker_probe)
    begin
      send_request :post, api_v1_timesheet_entry_index_path, params:, headers: auth_headers(marker_user)
    ensure
      Rails.event.unsubscribe(marker_probe)
    end

    expect(response).to be_successful
    expect(json_response["notice"]).to match("Timesheet created")
    expect(marker_probe.seen).to eq("legacy_gateway")
    expect(TimesheetEntry.find(json_response["entry"]["id"]).note).to eq("Legacy marker")
    after_commit = ActiveRecord::Base.connection.select_value("SELECT current_setting('miru.writer', true)")
    expect(after_commit.to_s).to eq("")
  end
end

