RSpec.describe "Api::V1::TimesheetEntry gateway forwarded lifecycle", type: :request do
  let(:company) { create(:company) }
  let(:project) { create(:project, billable: true, client: create(:client, company:)) }
  let(:admin) { create(:user, current_workspace_id: company.id) }
  let(:base_url) { "http://timekeeping.test" }
  let(:fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }

  before do
    create(:employment, company:, user: admin)
    admin.add_role(:admin, company)
    fake.register_company(id: company.id, edit_days: company.timesheet_edit_days)
    fake.register_user(id: admin.id, company_id: company.id, role: "admin")
    fake.register_project(id: project.id, company_id: company.id)
    route_timekeeping_to_fake(fake, base_url:)
    TimekeepingOwnership.current.update!(owner: "timekeeping", generation: 2, handoff_step: nil)
    fake.generation = 2
    sign_in admin
  end

  def with_forwarding_env(&block)
    with_timekeeping_env("TIMEKEEPING_BASE_URL", base_url) do
      with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem, &block)
    end
  end

  # "An entry created while Timekeeping owns the data can be updated and deleted at once while snapshot delivery is paused"
  # No projection consumer runs in this example, so snapshot delivery is paused.
  it "creates, updates and deletes an entry Timekeeping owns with no local row and the existing JSON" do
    with_forwarding_env do
      expect do
        send_request :post, api_v1_timesheet_entry_index_path, params: {
          project_id: project.id, user_id: admin.id,
          timesheet_entry: { duration: 20, work_date: Date.current, note: "Forwarded", bill_status: :unbilled }
        }, headers: auth_headers(admin)
      end.not_to change(TimesheetEntry, :count)
      expect(response).to have_http_status(:ok)
      expect(json_response["notice"]).to match("Timesheet created")
      expect(json_response["entry"]).to include("project_id" => project.id, "note" => "Forwarded", "duration" => 20.0)
      entry_id = json_response["entry"]["id"]

      send_request :patch, api_v1_timesheet_entry_path(entry_id), params: {
        project_id: project.id,
        timesheet_entry: { duration: 30, work_date: Date.current, note: "Edited", bill_status: :unbilled }
      }, headers: auth_headers(admin)
      expect(response).to have_http_status(:ok)
      expect(json_response["notice"]).to match("Timesheet updated")
      expect(json_response["entry"]).to include("id" => entry_id, "note" => "Edited")

      send_request :delete, api_v1_timesheet_entry_path(entry_id), headers: auth_headers(admin)
      expect(response).to have_http_status(:ok)
      expect(json_response["notice"]).to match("Timesheet deleted")
      expect(fake.stored_entry(entry_id)["discarded_at"]).not_to be_nil
    end

    expect(TimesheetEntry.count).to eq(0)
  end
end


RSpec.describe "Api::V1::TimesheetEntry gateway forwarded create headers", type: :request do
  let(:company) { create(:company) }
  let(:project) { create(:project, billable: true, client: create(:client, company:)) }
  let(:admin) { create(:user, current_workspace_id: company.id) }
  let(:colleague) { create(:user, current_workspace_id: company.id) }
  let(:base_url) { "http://timekeeping.test" }
  let(:fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }

  before do
    create(:employment, company:, user: admin)
    admin.add_role(:employee, company)
    admin.add_role(:admin, company)
    create(:employment, company:, user: colleague)
    colleague.add_role(:employee, company)
    fake.register_company(id: company.id, edit_days: company.timesheet_edit_days)
    fake.register_user(id: admin.id, company_id: company.id, role: "admin")
    fake.register_user(id: colleague.id, company_id: company.id, role: "employee")
    fake.register_project(id: project.id, company_id: company.id)
    route_timekeeping_to_fake(fake, base_url:)
    TimekeepingOwnership.current.update!(owner: "timekeeping", generation: 2, handoff_step: nil)
    fake.generation = 2
    sign_in admin
  end

  def forwarded_header(request, name)
    request.fetch(:headers).find { |key, _value| key.to_s.casecmp?(name) }&.last
  end

  # "A forwarded create has token `sub` equal to the signed-in user, body `user_id` equal to the target,
  # `X-Request-Id` equal to `request.request_id`, `Ownership-Generation` set, and no local row."
  it "forwards an employee-first admin's create for a colleague signed as the admin with the request id and generation" do
    with_timekeeping_env("TIMEKEEPING_BASE_URL", base_url) do
      with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem) do
        expect do
          send_request :post, api_v1_timesheet_entry_index_path, params: {
            project_id: project.id, user_id: colleague.id,
            timesheet_entry: { duration: 20, work_date: Date.current, note: "For colleague", bill_status: :unbilled }
          }, headers: auth_headers(admin)
        end.not_to change(TimesheetEntry, :count)
      end
    end

    expect(response).to have_http_status(:ok)
    create_request = fake.requests.find { |request| request.fetch(:method) == "POST" }
    bearer = forwarded_header(create_request, "Authorization").delete_prefix("Bearer ")
    claims = Timekeeping::UserToken.verify(bearer, public_key: timekeeping_key_pair.public_key)
    expect(claims.user_id).to eq(admin.id)
    expect(claims.user_id).not_to eq(colleague.id)
    expect(create_request.fetch(:body)["user_id"]).to eq(colleague.id)
    expect(forwarded_header(create_request, "X-Request-Id")).to eq(response.headers["X-Request-Id"])
    expect(forwarded_header(create_request, "X-Request-Id")).to be_present
    expect(forwarded_header(create_request, "Ownership-Generation").to_s).to eq("2")
    expect(json_response["entry"]["team_member"]).to eq(colleague.full_name)
  end
end


