        }, headers: auth_headers(admin)
        expect(response).to have_http_status(:ok)
        update_request_id = response.headers["X-Request-Id"]
        update_calls = fake.requests.dup
        expect(update_calls.map { |request| request.fetch(:method) }).to eq(%w[GET PATCH])
        expect(update_calls.map { |request| forwarded_header(request, "X-Request-Id") }).to all(eq(update_request_id))

        send_request :delete, api_v1_timesheet_entry_path(entry_id), headers: auth_headers(admin)
        expect(response).to have_http_status(:ok)
        delete_calls = fake.requests.drop(update_calls.size)
        expect(delete_calls.map { |request| request.fetch(:method) }).to eq(%w[GET DELETE])
        expect(delete_calls.map { |request| forwarded_header(request, "X-Request-Id") }).to all(eq(response.headers["X-Request-Id"]))
        expect(response.headers["X-Request-Id"]).not_to eq(update_request_id)
      end
    end
  end
end

