RSpec.describe "Api::V1::TimesheetEntry gateway prepared state default", type: :request do
  let(:company) { create(:company) }
  let(:project) { create(:project, billable: true, client: create(:client, company:)) }
  let(:user) { create(:user, current_workspace_id: company.id) }
  let!(:entry) { create(:timesheet_entry, user:, project:, work_date: Date.current) }

  before do
    create(:employment, company:, user:)
    user.add_role(:admin, company)
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", generation: 3, handoff_step: nil)
    sign_in user
  end

  # "Its default is a new `Timekeeping::Gateway::UnavailableLocalOwner`, which refuses with `OwnershipMoving`."
  # The legacy row must stay untouched: the prepared store owns the data, so the legacy table is never written.
  it "refuses a delete in the prepared state with no local owner wired and leaves the legacy row kept" do
    send_request :delete, api_v1_timesheet_entry_path(entry), headers: auth_headers(user)

    expect(response).to have_http_status(:service_unavailable)
    expect(json_response["reason"]).to eq("ownership_moving")
    expect(entry.reload).not_to be_discarded
  end
end

RSpec.describe "Api::V1::TimesheetEntry gateway legacy at raised generation", type: :request do
  let(:company) { create(:company) }
  let(:project) { create(:project, billable: true, client: create(:client, company:)) }
  let(:user) { create(:user, current_workspace_id: company.id) }

  before do
    create(:employment, company:, user:)
    user.add_role(:employee, company)
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "legacy", generation: 2, handoff_step: nil)
    sign_in user
  end

  # "An aborted handoff keeps the raised generation while the legacy store still holds the data,
  # so a legacy store at generation above 1 routes as legacy."
  it "writes locally for a legacy store left at a raised generation by an aborted handoff" do
    expect do
      send_request :post, api_v1_timesheet_entry_index_path, params: {
        project_id: project.id, user_id: user.id,
        timesheet_entry: { duration: 20, work_date: Date.current, note: "Legacy again", bill_status: :unbilled }
      }, headers: auth_headers(user)
    end.to change(TimesheetEntry, :count).by(1)

    expect(response).to have_http_status(:ok)
    expect(json_response["notice"]).to match("Timesheet created")
    expect(TimesheetEntry.find(json_response["entry"]["id"]).note).to eq("Legacy again")
    expect(WebMock).not_to have_requested(:any, /timekeeping/)
  end
end

RSpec.describe "Api::V1::TimesheetEntry gateway refusal event", type: :request do
  let(:company) { create(:company) }
  let(:project) { create(:project, billable: true, client: create(:client, company:)) }
  let(:user) { create(:user, current_workspace_id: company.id) }

  before do
    create(:employment, company:, user:)
    user.add_role(:admin, company)
    TimekeepingOwnership.current.update!(handoff_step: "settle")
    sign_in user
  end

  # "Emit `503 ownership_moving` and `409 stale_generation` counts with `company_id`, `request_id` and actor kind."
  # "It carries reason, company_id, request_id and actor_kind from the context, and never the token or the body."
  it "reports a refused entry write with reason, company_id, request_id and actor kind only" do
    event = assert_event_reported("Timekeeping::EntryWriteRefused") do
      send_request :post, api_v1_timesheet_entry_index_path, params: {
        project_id: project.id, user_id: user.id,
        timesheet_entry: { duration: 20, work_date: Date.current, note: "Secret note", bill_status: :unbilled }
      }, headers: auth_headers(user)
    end

    expect(response).to have_http_status(:service_unavailable)
    data = event[:payload].to_h.fetch(:data).to_h.transform_keys(&:to_sym)
    expect(data).to eq(
      reason: "ownership_moving",
      company_id: company.id,
      request_id: response.headers["X-Request-Id"],
      actor_kind: "user"
    )
    expect(event[:payload].to_h.to_s).not_to include("Secret note")
  end
end


RSpec.describe "Api::V1::TimesheetEntry gateway provider stale generation", type: :request do
  let(:company) { create(:company) }
  let(:project) { create(:project, billable: true, client: create(:client, company:)) }
  let(:admin) { create(:user, current_workspace_id: company.id) }
  let(:base_url) { "http://timekeeping.test" }
  let(:fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }

  before do
    create(:employment, company:, user: admin)
    admin.add_role(:admin, company)
    fake.register_company(id: company.id, edit_days: company.timesheet_edit_days)
    fake.register_user(id: admin.id, company_id: company.id, role: "admin")
    fake.register_project(id: project.id, company_id: company.id)
    fake.generation = 3
    route_timekeeping_to_fake(fake, base_url:)
    TimekeepingOwnership.current.update!(owner: "timekeeping", generation: 2, handoff_step: nil)
    sign_in admin
  end

  # "A stale generation gives 409."
  it "answers 409 stale_generation when Timekeeping refuses the forwarded generation" do
    with_timekeeping_env("TIMEKEEPING_BASE_URL", base_url) do
      with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem) do
        send_request :post, api_v1_timesheet_entry_index_path, params: {
          project_id: project.id, user_id: admin.id,
          timesheet_entry: { duration: 20, work_date: Date.current, note: "Stale", bill_status: :unbilled }
        }, headers: auth_headers(admin)
      end
    end

    expect(response).to have_http_status(:conflict)
    expect(json_response["reason"]).to eq("stale_generation")
    expect(json_response["errors"]).to be_present
    expect(TimesheetEntry.count).to eq(0)
  end
end

RSpec.describe "Api::V1::TimesheetEntry legacy writes through the gateway", type: :request do
  # "Legacy monolith: it writes `timesheet_entries` as today"; the routes and JSON stay as they are.
  it "keeps the legacy update and delete JSON and soft-deletes the row through the gateway" do
    company = create(:company)
    project = create(:project, billable: true, client: create(:client, company:))
    user = create(:user, current_workspace_id: company.id)
    create(:employment, company:, user:)
    user.add_role :admin, company
    entry = create(:timesheet_entry, user:, project:, bill_status: :unbilled)
    sign_in user

    send_request :patch, api_v1_timesheet_entry_path(entry),
      params: { project_id: project.id, timesheet_entry: { duration: 45, work_date: Date.current, note: "edited", bill_status: :unbilled } },
      headers: auth_headers(user)

    expect(response).to have_http_status(:ok)
    expect(json_response["notice"]).to match("Timesheet updated")
    expect(json_response["entry"]["id"]).to eq(entry.id)
    expect(json_response["entry"]["note"]).to eq("edited")
    expect(entry.reload.note).to eq("edited")

    send_request :delete, api_v1_timesheet_entry_path(entry), headers: auth_headers(user)

    expect(response).to be_successful
    expect(json_response.keys).to eq(["notice"])
    expect(json_response["notice"]).to match("Timesheet deleted")
    expect(TimesheetEntry.find(entry.id).discarded_at).to be_present
  end
end

RSpec.describe "Api::V1::TimesheetEntry gateway handoff refusal on update", type: :request do
  let(:company) { create(:company) }
  let(:admin) { create(:user, current_workspace_id: company.id) }
  let(:project) { create(:project, billable: true, client: create(:client, company:)) }
  let!(:entry) { create(:timesheet_entry, user: admin, project:, work_date: Time.current, note: "before handoff") }

  before do
    create(:employment, company:, user: admin)
    admin.add_role :admin, company
    sign_in admin
  end

  # "When `handoff_step` is set, the gateway refuses entry writes, prepares and service commands with a retryable `503 ownership_moving`."
  # Acceptance: "503 ownership_moving and 409 stale_generation counts are emitted with company_id, request_id and actor kind"
  it "refuses a legacy update during a handoff with 503 before the entry changes and counts the refusal once" do
    TimekeepingOwnership.current.update!(handoff_step: "settle")
    refusals = RailsEventViewer::Entry.where(name: "Timekeeping::EntryWriteRefused")

    expect do
      send_request :patch, api_v1_timesheet_entry_path(entry), params: {
        project_id: project.id, timesheet_entry: { note: "written during handoff" }
      }, headers: auth_headers(admin)
    end.to change { refusals.count }.by(1)

    expect(response).to have_http_status(503)
    expect(response.headers["Retry-After"]).to be_present
    expect(json_response["reason"]).to eq("ownership_moving")
    expect(entry.reload.note).to eq("before handoff")
    expect(refusals.last.payload["data"]).to include(
      "reason" => "ownership_moving", "company_id" => company.id,
      "request_id" => response.headers["X-Request-Id"], "actor_kind" => "user"
    )
  end
end

