  before do
    create(:employment, company:, user: admin)
    admin.add_role :admin, company
    sign_in admin
  end

  # "A missing row or an unknown owner also refuses (fail closed). It never falls back to legacy and never answers 404."
  it "answers a delete with 503 ownership_moving, never 404, when the ownership row is missing" do
    TimekeepingOwnership.delete_all

    send_request :delete, api_v1_timesheet_entry_path(entry), headers: auth_headers(admin)

    expect(response).to have_http_status(503)
    expect(json_response["reason"]).to eq("ownership_moving")
    expect(entry.reload).not_to be_discarded
  end
end

RSpec.describe "Api::V1::TimesheetEntry gateway when Timekeeping reports a stale generation", type: :request do
  let(:base_url) { "http://timekeeping.test" }
  let(:company) { create(:company) }
  let(:admin) { create(:user, current_workspace_id: company.id) }
  let(:project) { create(:project, billable: true, client: create(:client, company:)) }
  let(:fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }

  around do |example|
    with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem) do
      with_timekeeping_env(Timekeeping::EntryApiClient::BASE_URL_ENV, base_url) { example.run }
    end
  end

  before do
    create(:employment, company:, user: admin)
    admin.add_role :admin, company
    fake.register_company(id: company.id, edit_days: company.timesheet_edit_days)
    fake.register_user(id: admin.id, company_id: company.id, role: "admin")
    fake.register_project(id: project.id, company_id: company.id)
    route_timekeeping_to_fake(fake, base_url:)
    TimekeepingOwnership.current.update!(owner: "timekeeping", generation: 2, handoff_step: nil)
    sign_in admin
  end

  # "Emit `503 ownership_moving` and `409 stale_generation` counts with `company_id`, `request_id` and actor kind."
  # Timekeeping has moved past the monolith's generation, so the forwarded write is stale on arrival.
  it "turns a Timekeeping stale_generation answer into 409 with one refusal event and no local row" do
    fake.generation = 7
    refusals = RailsEventViewer::Entry.where(name: "Timekeeping::EntryWriteRefused")

    expect do
      expect do
        send_request :post, api_v1_timesheet_entry_index_path, params: {
          project_id: project.id, user_id: admin.id,
          timesheet_entry: { duration: 30, work_date: Date.current.iso8601, note: "stale", bill_status: :unbilled }
        }, headers: auth_headers(admin)
      end.to change { refusals.count }.by(1)
    end.not_to change(TimesheetEntry, :count)

    expect(response).to have_http_status(409)
    expect(json_response["reason"]).to eq("stale_generation")
    expect(refusals.last.payload["data"]).to include("reason" => "stale_generation", "company_id" => company.id)
  end
end

RSpec.describe "Api::V1::TimesheetEntry gateway with a foreign Timekeeping entry id", type: :request do
  let(:base_url) { "http://timekeeping.test" }
  let(:company) { create(:company) }
  let(:other_company) { create(:company) }
  let(:admin) { create(:user, current_workspace_id: company.id) }
  let(:project) { create(:project, billable: true, client: create(:client, company:)) }
  let(:other_project) { create(:project, billable: true, client: create(:client, company: other_company)) }
  let(:other_user) { create(:user, current_workspace_id: other_company.id) }
  let(:fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }

  around do |example|
    with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem) do
      with_timekeeping_env(Timekeeping::EntryApiClient::BASE_URL_ENV, base_url) { example.run }
    end
  end

  before do
    create(:employment, company:, user: admin)
    admin.add_role :admin, company
    fake.register_company(id: company.id, edit_days: company.timesheet_edit_days)
    fake.register_user(id: admin.id, company_id: company.id, role: "admin")
    fake.register_project(id: project.id, company_id: company.id)
    route_timekeeping_to_fake(fake, base_url:)
    TimekeepingOwnership.current.update!(owner: "timekeeping", generation: 2, handoff_step: nil)
    fake.generation = 2
    sign_in admin
  end

  # Acceptance: "Another company's user or entry gets 404."
  it "answers 404 for another company's Timekeeping entry id and never forwards the update" do
    foreign_id = fake.add_entry(company_id: other_company.id, user_id: other_user.id, project_id: other_project.id,
                                note: "theirs").fetch("id")

    send_request :patch, api_v1_timesheet_entry_path(foreign_id), params: {
      project_id: project.id, timesheet_entry: { note: "overwritten across companies" }
    }, headers: auth_headers(admin)

    expect(response).to have_http_status(:not_found)
    expect(fake.requests.pluck(:method)).not_to include("PATCH")
    expect(fake.stored_entry(foreign_id)["note"]).to eq("theirs")
  end
end

RSpec.describe "Api::V1::TimesheetEntry gateway forwarded note-only edit", type: :request do
  let(:base_url) { "http://timekeeping.test" }
  let(:company) { create(:company) }
  let(:admin) { create(:user, current_workspace_id: company.id) }
  let(:project) { create(:project, billable: true, client: create(:client, company:)) }
  let(:fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }

  around do |example|
    with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem) do
      with_timekeeping_env(Timekeeping::EntryApiClient::BASE_URL_ENV, base_url) { example.run }
    end
  end

  before do
    create(:employment, company:, user: admin)
    admin.add_role :admin, company
    fake.register_company(id: company.id, edit_days: company.timesheet_edit_days)
    fake.register_user(id: admin.id, company_id: company.id, role: "admin")
    fake.register_project(id: project.id, company_id: company.id)
    route_timekeeping_to_fake(fake, base_url:)
    TimekeepingOwnership.current.update!(owner: "timekeeping", generation: 2, handoff_step: nil)
    fake.generation = 2
    sign_in admin
  end

  # Acceptance: "Web and mobile create, update and destroy go through Timekeeping::Gateway and keep their routes and JSON"
  # Today's update permits no source fields, so a forwarded edit must not overwrite them with create defaults.
  it "keeps an imported entry's source and metadata when a forwarded edit changes only the note" do
    entry_id = fake.add_entry(company_id: company.id, user_id: admin.id, project_id: project.id,
                              work_date: Date.current.iso8601, note: "imported", source: "import",
                              source_metadata: { "tool" => "harvest" }).fetch("id")

    send_request :patch, api_v1_timesheet_entry_path(entry_id), params: {
      project_id: project.id, timesheet_entry: { note: "edited" }
    }, headers: auth_headers(admin)

    expect(response).to have_http_status(:ok)
    stored = fake.stored_entry(entry_id)
    expect(stored["note"]).to eq("edited")
    expect(stored["source"]).to eq("import")
    expect(stored["source_metadata"]).to eq("tool" => "harvest")
  end
end

RSpec.describe "Api::V1::TimesheetEntry#destroy during a handoff", type: :request do
  let(:handoff_delete_company) { create(:company) }
  let(:handoff_delete_admin) do
    create(:user, email: "handoff-delete-#{SecureRandom.hex(6)}@example.com",
                  current_workspace_id: handoff_delete_company.id)
  end
  let(:handoff_delete_project) { create(:project, client: create(:client, company: handoff_delete_company)) }
  let!(:handoff_delete_entry) do
    create(:timesheet_entry, user: handoff_delete_admin, project: handoff_delete_project, work_date: Time.current)
  end

  before do
    create(:employment, company: handoff_delete_company, user: handoff_delete_admin)
    handoff_delete_admin.add_role :admin, handoff_delete_company
    sign_in handoff_delete_admin
  end

  it "refuses a legacy delete that arrives after a handoff began with 503 ownership_moving and leaves the entry kept" do
    # The entry is looked up before the handoff starts; the delete must still
    # be refused by the fence, not discard the row the handoff is copying.
    # "When `handoff_step` is set, the gateway refuses entry writes, prepares and service commands with a retryable `503 ownership_moving`."
    TimekeepingOwnership.where(id: TimekeepingOwnership::SINGLETON_ID).update_all(handoff_step: "close_admission")

    send_request :delete, api_v1_timesheet_entry_path(handoff_delete_entry), headers: auth_headers(handoff_delete_admin)

    expect(response).to have_http_status(503)
    expect(json_response["reason"]).to eq("ownership_moving")
    expect(response.headers["Retry-After"]).to eq(Timekeeping::BillingFence::RETRY_AFTER_SECONDS.to_s)
    expect(json_response["errors"]).not_to eq(I18n.t("errors.ownership_moving"))
    expect(handoff_delete_entry.reload).not_to be_discarded
  end
end

RSpec.describe "Api::V1::TimesheetEntry gateway reserved entry for an employee-first admin", type: :request do
  let(:company) { create(:company) }
  let(:project) { create(:project, billable: true, client: create(:client, company:)) }
  let(:employee_first_admin) { create(:user, current_workspace_id: company.id) }
  let(:base_url) { "http://timekeeping.test" }
  let(:reserved_fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }

  before do
    create(:employment, company:, user: employee_first_admin)
    employee_first_admin.add_role(:employee, company)
    employee_first_admin.add_role(:admin, company)
    reserved_fake.register_company(id: company.id, edit_days: company.timesheet_edit_days)
    reserved_fake.register_user(id: employee_first_admin.id, company_id: company.id, role: "admin")
    reserved_fake.register_project(id: project.id, company_id: company.id)
    route_timekeeping_to_fake(reserved_fake, base_url:)
    TimekeepingOwnership.current.update!(owner: "timekeeping", generation: 2, handoff_step: nil)
    reserved_fake.generation = 2
    sign_in employee_first_admin
  end

  it "refuses an edit of a reserved Timekeeping entry with 403 and leaves the entry unchanged" do
    reserved_entry_id = reserved_fake.add_entry(company_id: company.id, user_id: employee_first_admin.id,
                                                project_id: project.id, work_date: Date.current.iso8601,
                                                note: "Reserved").fetch("id")
    reserved_fake.add_reservation(entry_id: reserved_entry_id, invoice_id: 1, state: "provisional", disposition: "keep")

    with_timekeeping_env("TIMEKEEPING_BASE_URL", base_url) do
      with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem) do
        send_request :patch, api_v1_timesheet_entry_path(reserved_entry_id), params: {
          project_id: project.id,
          timesheet_entry: { duration: 10, work_date: Date.current, note: "Edited while reserved", bill_status: :unbilled }
        }, headers: auth_headers(employee_first_admin)
      end
    end

    expect(response).to have_http_status(:forbidden)
    expect(reserved_fake.stored_entry(reserved_entry_id)["note"]).to eq("Reserved")
  end
end

RSpec.describe "Api::V1::TimesheetEntry gateway legacy create for a colleague", type: :request do
  let(:company) { create(:company) }
  let(:project) { create(:project, billable: true, client: create(:client, company:)) }
  let(:colleague) { create(:user, current_workspace_id: company.id) }

  before do
    create(:employment, company:, user: colleague)
    colleague.add_role(:employee, company)
  end

  def legacy_create_for_colleague(acting_user)
    sign_in acting_user
    send_request :post, api_v1_timesheet_entry_index_path, params: {
      project_id: project.id, user_id: colleague.id,
      timesheet_entry: { duration: 15, work_date: Date.current, note: "Legacy for colleague", bill_status: :unbilled }
    }, headers: auth_headers(acting_user)
  end

  it "lets an owner and an employee-first admin create a colleague's entry in the legacy store" do
    owner = create(:user, current_workspace_id: company.id)
    create(:employment, company:, user: owner)
    owner.add_role(:owner, company)
    employee_first_admin = create(:user, current_workspace_id: company.id)
    create(:employment, company:, user: employee_first_admin)
    employee_first_admin.add_role(:employee, company)
    employee_first_admin.add_role(:admin, company)

    [owner, employee_first_admin].each do |acting_user|
      expect { legacy_create_for_colleague(acting_user) }.to change(TimesheetEntry.where(user_id: colleague.id), :count).by(1)
      expect(response).to have_http_status(:ok)
      expect(json_response["entry"]["team_member"]).to eq(colleague.full_name)
    end
  end
end
